-- Private site settings, immutable publish history, activity and asset metadata.
create table public.site_configuration (
  id integer primary key check (id = 1),
  version bigint not null default 0 check (version >= 0),
  draft jsonb not null check (jsonb_typeof(draft) = 'object'),
  published jsonb not null check (jsonb_typeof(published) = 'object'),
  updated_at timestamptz not null default now()
);
create table public.site_revisions (
  id uuid primary key default gen_random_uuid(),
  version bigint not null check (version >= 0),
  config jsonb not null check (jsonb_typeof(config) = 'object'),
  note text not null default '' check (length(note) <= 300),
  created_at timestamptz not null default now()
);
create table public.site_activity (
  id uuid primary key default gen_random_uuid(),
  action text not null check (length(action) between 1 and 100),
  detail text not null default '' check (length(detail) <= 500),
  created_at timestamptz not null default now()
);
create table public.site_assets (
  id uuid primary key,
  kind text not null check (kind in ('guide', 'release')),
  mime text not null check (mime in ('image/png', 'image/jpeg', 'image/webp', 'application/zip')),
  size bigint not null check (size between 1 and 20971520),
  name text not null check (length(name) between 1 and 120),
  object_path text not null unique,
  created_at timestamptz not null default now(),
  check ((kind = 'guide' and mime like 'image/%' and size <= 5242880) or (kind = 'release' and mime = 'application/zip'))
);
create index site_revisions_created_idx on public.site_revisions (created_at desc);
create index site_activity_created_idx on public.site_activity (created_at desc);
create table public.site_uploads (
  id uuid primary key,
  kind text not null check (kind in ('guide','release')),
  mime text not null check (mime in ('image/png','image/jpeg','image/webp','application/zip')),
  size bigint not null check (size between 1 and 20971520),
  name text not null check (length(name) between 1 and 120),
  object_path text not null unique,
  expires_at timestamptz not null default now() + interval '30 minutes'
);
alter table public.site_uploads enable row level security;
alter table public.site_uploads force row level security;
revoke all on public.site_uploads from public, anon, authenticated, service_role;
grant select, insert, delete on public.site_uploads to service_role;
alter table public.site_configuration enable row level security;
alter table public.site_configuration force row level security;
alter table public.site_revisions enable row level security;
alter table public.site_revisions force row level security;
alter table public.site_activity enable row level security;
alter table public.site_activity force row level security;
alter table public.site_assets enable row level security;
alter table public.site_assets force row level security;
revoke all on public.site_configuration, public.site_revisions, public.site_activity, public.site_assets from public, anon, authenticated, service_role;
grant select, insert, update on public.site_configuration to service_role;
grant select, insert on public.site_revisions, public.site_activity, public.site_assets to service_role;

