insert into public.site_revisions (version, config, note) select 0, published, 'Initial website' from public.site_configuration;

create function public.manage_site_configuration(p_operation text, p_config jsonb, p_expected_version bigint, p_note text default '', p_history_id uuid default null)
returns bigint language plpgsql security invoker set search_path = public, pg_temp as $$
declare current_row public.site_configuration%rowtype; new_version bigint; restored jsonb;
begin
  select * into strict current_row from public.site_configuration where id=1 for update;
  if p_expected_version is null or current_row.version <> p_expected_version then raise exception 'VERSION_CONFLICT'; end if;
  if p_note is null or length(p_note) > 300 then raise exception 'INVALID_NOTE'; end if;
  new_version := current_row.version + 1;
  if p_operation = 'save' then
    if p_config is null or jsonb_typeof(p_config) <> 'object' then raise exception 'INVALID_SITE_CONFIG'; end if;
    update public.site_configuration set draft=p_config, version=new_version, updated_at=now() where id=1;
  elsif p_operation = 'publish' then
    update public.site_configuration set published=draft, version=new_version, updated_at=now() where id=1;
    insert into public.site_revisions (version, config, note) values (new_version, current_row.draft, p_note);
  elsif p_operation = 'restore' then
    select config into strict restored from public.site_revisions where id=p_history_id;
    update public.site_configuration set draft=restored, version=new_version, updated_at=now() where id=1;
  else raise exception 'INVALID_OPERATION';
  end if;
  insert into public.site_activity (action, detail) values (p_operation, case when p_operation='publish' then p_note when p_operation='restore' then 'Restored revision to draft' else 'Saved website draft' end);
  return new_version;
end $$;
revoke all on function public.manage_site_configuration(text,jsonb,bigint,text,uuid) from public, anon, authenticated;
grant execute on function public.manage_site_configuration(text,jsonb,bigint,text,uuid) to service_role;

create function public.revoke_activation_key(p_key_id uuid)
returns void language plpgsql security invoker set search_path = public, pg_temp as $$
begin
  update public.activation_keys set status='revoked' where id=p_key_id and status<>'revoked';
  if not found then raise exception 'KEY_NOT_AVAILABLE'; end if;
  insert into public.site_activity (action, detail) values ('revoke_key', 'Revoked activation key ' || p_key_id::text);
end $$;
revoke all on function public.revoke_activation_key(uuid) from public, anon, authenticated;
grant execute on function public.revoke_activation_key(uuid) to service_role;

-- Private immutable assets; all reads pass through the server's access checks.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('site-assets', 'site-assets', false, 20971520, array['image/png','image/jpeg','image/webp','application/zip'])
on conflict (id) do nothing;
